macro_rules! impl_92 {
    () => {
        deps!();
        impl Stat { # [doc = " Detect whether this stat entry is racy if stored in a file index with `timestamp`."] # [doc = ""] # [doc = " An index entry is considered racy if it's `mtime` is larger or equal to the index `timestamp`."] # [doc = " The index `timestamp` marks the point in time before which we definitely resolved the racy git problem"] # [doc = " for all index entries so any index entries that changed afterwards will need to be examined for"] # [doc = " changes by actually reading the file from disk at least once."] pub fn is_racy (& self , timestamp : FileTime , Options { check_stat , use_nsec , .. } : Options ,) -> bool { match timestamp . unix_seconds () . cmp (& i64 :: from (self . mtime . secs)) { Ordering :: Less => true , Ordering :: Equal if use_nsec && check_stat => timestamp . nanoseconds () <= self . mtime . nsecs , Ordering :: Equal => true , Ordering :: Greater => false , } } # [doc = " Compares the stat information of two index entries."] # [doc = ""] # [doc = " Intuitively this is basically equivalent to `self == other`."] # [doc = " However there a lot of nobs in git that tweak whether certain stat information is used when checking"] # [doc = " equality, see [`Options`]."] # [doc = " This function respects those options while performing the stat comparison and may therefore ignore some fields."] pub fn matches (& self , other : & Self , Options { trust_ctime , check_stat , use_nsec , use_stdev , } : Options ,) -> bool { if self . mtime . secs != other . mtime . secs { return false ; } if check_stat && use_nsec && self . mtime . nsecs != other . mtime . nsecs { return false ; } if self . size != other . size { return false ; } if trust_ctime { if self . ctime . secs != other . ctime . secs { return false ; } if check_stat && use_nsec && self . ctime . nsecs != other . ctime . nsecs { return false ; } } if check_stat { if use_stdev && self . dev != other . dev { return false ; } self . ino == other . ino && self . gid == other . gid && self . uid == other . uid } else { true } } # [doc = " Creates stat information from file metadata."] # [doc = ""] # [doc = " The information passed to this function should originate from a function like"] # [doc = " `symlink_metadata`/`lstat` or `File::metadata`/`fstat`."] # [doc = ""] # [doc = " The data are adjusted for use in the index, using default values of fields that are not"] # [doc = " meaningful on the target operating system or that are unavailable, and truncating data"] # [doc = " where doing so does not lose essential information for keeping track of file status."] pub fn from_fs (stat : & crate :: fs :: Metadata) -> Result < Stat , SystemTimeError > { let mtime = stat . modified () . unwrap_or (std :: time :: UNIX_EPOCH) ; let ctime = stat . created () . unwrap_or (std :: time :: UNIX_EPOCH) ; # [cfg (windows)] let res = Stat { mtime : mtime . try_into () ? , ctime : ctime . try_into () ? , dev : 0 , ino : 0 , uid : 0 , gid : 0 , size : stat . len () as u32 , } ; # [cfg (not (windows))] let res = { Stat { mtime : mtime . try_into () . unwrap_or_default () , ctime : ctime . try_into () . unwrap_or_default () , dev : stat . dev () as u32 , ino : stat . ino () as u32 , uid : stat . uid () , gid : stat . gid () , size : stat . len () as u32 , } } ; Ok (res) } }
    };
}

